from pathlib import Path
import subprocess,tempfile
p=Path(__file__).parent
cases=[('3\n5 8 14\n4 9', '4'), ('15\n76 23 14 14 74 27 68 15 27 73 39 67 67 11 64\n34 72', '51'), ('7\n79 40 7 63 28 6 31\n84 89', '89'), ('10\n50 57 73 23 27 92 40 23 94 81\n49 75', '65'), ('7\n61 22 8 31 2 67 90\n17 31', '17'), ('14\n62 71 11 95 59 24 18 91 48 32 77 84 98 97\n62 71', '66'), ('8\n90 45 62 30 61 33 3 80\n84 96', '96'), ('5\n23 24 99 80 54\n20 99', '39'), ('11\n7 62 88 31 56 10 34 81 65 86 43\n60 70', '70'), ('15\n22 51 67 41 26 39 29 88 45 37 90 6 77 92 31\n37 84', '59'), ('12\n98 86 4 24 70 2 68 11 46 47 32 3\n39 72', '57'), ('2\n6 25\n84 99', '99'), ('1\n82\n5 52', '5'), ('9\n81 75 45 5 78 66 9 55 13\n81 84', '84'), ('11\n95 70 13 2 56 12 7 50 94 73 82\n17 38', '31'), ('15\n45 65 41 59 24 98 92 70 58 33 12 8 53 80 32\n6 73', '18'), ('2\n99 87\n61 100', '61'), ('7\n100 76 71 26 62 15 58\n49 79', '49'), ('13\n32 43 45 15 72 46 78 100 25 31 36 64 8\n63 92', '89'), ('14\n32 20 61 2 94 29 14 4 76 13 28 96 74 22\n90 94', '90'), ('10\n21 36 92 92 19 61 82 26 68 83\n34 47', '47'), ('9\n25 64 21 23 7 43 96 76 36\n88 91', '88'), ('3\n95 87 84\n68 89', '68'), ('2\n77 90\n77 90', '83'), ('7\n25 70 92 54 69 13 76\n60 62', '61'), ('12\n94 3 24 15 4 53 95 35 100 50 68 15\n23 57', '42')]
with tempfile.TemporaryDirectory() as d:
 subprocess.run(['javac','-d',d,str(p/'Solution.java')],check=True)
 for data,want in cases:
  result=subprocess.run(['java','-cp',d,'Solution'],input=data,text=True,capture_output=True,check=True,timeout=8)
  assert result.stdout.strip()==want.strip(),(data,result.stdout,want)
print(str(len(cases))+' sample and original edge-case checks passed')
